/**
 * Wire protocol for the Codex app-server, as generated by
 * `codex app-server generate-json-schema` for codex-cli 0.147.0.
 *
 * Only the parts this adapter actually drives are modelled here. Every schema
 * is a loose object: the app server is versioned independently of us and adds
 * fields freely, so unknown fields are preserved rather than rejected
 * (plan section 6: "unknown event fields must not crash a compatible stream").
 *
 * Two details of the installed protocol are worth stating because they differ
 * from textbook JSON-RPC 2.0:
 *   - the server omits the `"jsonrpc": "2.0"` member on every frame it sends;
 *   - notifications carry an extra `emittedAtMs` member alongside `params`.
 * Both are tolerated here. We still send `jsonrpc` on our own frames because
 * the server accepts it and it keeps our transcripts self-describing.
 */
import { z } from 'zod';
import type { Policy } from '../../core/contracts.js';

// ---------------------------------------------------------------------------
// Methods (schema: ClientRequest.json / ServerNotification.json / ServerRequest.json)
// ---------------------------------------------------------------------------

export const CLIENT_METHOD = {
  initialize: 'initialize',
  threadStart: 'thread/start',
  threadResume: 'thread/resume',
  turnStart: 'turn/start',
  turnSteer: 'turn/steer',
  turnInterrupt: 'turn/interrupt',
  modelList: 'model/list',
} as const;

/** The only client notification the installed protocol defines. */
export const INITIALIZED_NOTIFICATION = 'initialized';

export const SERVER_NOTIFICATION = {
  threadStarted: 'thread/started',
  threadStatusChanged: 'thread/status/changed',
  turnStarted: 'turn/started',
  turnCompleted: 'turn/completed',
  turnDiffUpdated: 'turn/diff/updated',
  itemStarted: 'item/started',
  itemCompleted: 'item/completed',
  error: 'error',
  tokenUsageUpdated: 'thread/tokenUsage/updated',
} as const;

/**
 * Server -> client requests defined by ServerRequest.json. Every one of them
 * asks us to authorize something, so every one of them is answered by policy.
 */
export const SERVER_REQUEST = {
  commandExecutionApproval: 'item/commandExecution/requestApproval',
  fileChangeApproval: 'item/fileChange/requestApproval',
  permissionsApproval: 'item/permissions/requestApproval',
  toolUserInput: 'item/tool/requestUserInput',
  mcpElicitation: 'mcpServer/elicitation/request',
  toolCall: 'item/tool/call',
  legacyApplyPatchApproval: 'applyPatchApproval',
  legacyExecCommandApproval: 'execCommandApproval',
  chatgptAuthTokensRefresh: 'account/chatgptAuthTokens/refresh',
  attestationGenerate: 'attestation/generate',
} as const;

/** Method names whose payload is a streaming delta; noisy, and filtered from the normalized stream by default. */
const DELTA_METHODS = new Set([
  'item/agentMessage/delta',
  'item/plan/delta',
  'item/reasoning/textDelta',
  'item/reasoning/summaryTextDelta',
  'item/reasoning/summaryPartAdded',
  'item/commandExecution/outputDelta',
  'item/fileChange/outputDelta',
  'command/exec/outputDelta',
  'process/outputDelta',
  'item/mcpToolCall/progress',
]);

export function isDeltaMethod(method: string): boolean {
  return DELTA_METHODS.has(method);
}

// ---------------------------------------------------------------------------
// Frames
// ---------------------------------------------------------------------------

export const RequestIdSchema = z.union([z.string(), z.number().int()]);
export type RequestId = z.infer<typeof RequestIdSchema>;

export const RpcErrorSchema = z.looseObject({ code: z.number().int(), message: z.string(), data: z.unknown().optional() });
export type RpcErrorBody = z.infer<typeof RpcErrorSchema>;

/**
 * One decoded frame. The order of the checks matters: a server -> client
 * request has both `id` and `method`, a notification has only `method`.
 */
export const IncomingFrameSchema = z.looseObject({
  id: RequestIdSchema.optional(),
  method: z.string().optional(),
  params: z.unknown().optional(),
  result: z.unknown().optional(),
  error: RpcErrorSchema.optional(),
});
export type IncomingFrame = z.infer<typeof IncomingFrameSchema>;

export type DecodedFrame =
  | { readonly kind: 'response'; readonly id: RequestId; readonly result: unknown }
  | { readonly kind: 'error'; readonly id: RequestId; readonly error: RpcErrorBody }
  | { readonly kind: 'server_request'; readonly id: RequestId; readonly method: string; readonly params: unknown }
  | { readonly kind: 'notification'; readonly method: string; readonly params: unknown }
  | { readonly kind: 'undecodable'; readonly reason: string; readonly line: string };

export function decodeFrame(line: string): DecodedFrame {
  let parsed: unknown;
  try {
    parsed = JSON.parse(line);
  } catch {
    return { kind: 'undecodable', reason: 'invalid json', line };
  }
  const frame = IncomingFrameSchema.safeParse(parsed);
  if (!frame.success) return { kind: 'undecodable', reason: 'not a json-rpc frame', line };
  const { id, method, params, result, error } = frame.data;
  if (id !== undefined && method !== undefined) return { kind: 'server_request', id, method, params: params ?? {} };
  if (method !== undefined) return { kind: 'notification', method, params: params ?? {} };
  if (id !== undefined && error !== undefined) return { kind: 'error', id, error };
  if (id !== undefined) return { kind: 'response', id, result: result ?? null };
  return { kind: 'undecodable', reason: 'frame has neither id nor method', line };
}

// ---------------------------------------------------------------------------
// Requests and responses we drive
// ---------------------------------------------------------------------------

export const InitializeResultSchema = z.looseObject({
  userAgent: z.string().optional(),
  codexHome: z.string().optional(),
  platformOs: z.string().optional(),
  platformFamily: z.string().optional(),
});
export type InitializeResult = z.infer<typeof InitializeResultSchema>;

export const ThreadSchema = z.looseObject({
  id: z.string().min(1),
  cwd: z.string().optional(),
  cliVersion: z.string().optional(),
  ephemeral: z.boolean().optional(),
  modelProvider: z.string().optional(),
});

/** `thread/start` and `thread/resume` return the same shape (ThreadStartResponse / ThreadResumeResponse). */
export const ThreadStartResultSchema = z.looseObject({
  thread: ThreadSchema,
  model: z.string().optional(),
  modelProvider: z.string().optional(),
  reasoningEffort: z.string().nullish(),
  cwd: z.string().optional(),
  approvalPolicy: z.unknown().optional(),
  sandbox: z.unknown().optional(),
  serviceTier: z.string().nullish(),
});
export type ThreadStartResult = z.infer<typeof ThreadStartResultSchema>;

export const TurnStatusSchema = z.enum(['completed', 'interrupted', 'failed', 'inProgress']);
export type TurnStatus = z.infer<typeof TurnStatusSchema>;

export const TurnErrorSchema = z.looseObject({
  message: z.string(),
  codexErrorInfo: z.unknown().optional(),
  additionalDetails: z.string().nullish(),
});
export type TurnErrorBody = z.infer<typeof TurnErrorSchema>;

export const TurnSchema = z.looseObject({
  id: z.string().min(1),
  status: z.string().optional(),
  error: TurnErrorSchema.nullish(),
  durationMs: z.number().nullish(),
});

export const TurnStartResultSchema = z.looseObject({ turn: TurnSchema });
export type TurnStartResult = z.infer<typeof TurnStartResultSchema>;

export const TurnSteerResultSchema = z.looseObject({ turnId: z.string().min(1) });

export const ModelListResultSchema = z.looseObject({
  data: z.array(
    z.looseObject({
      id: z.string().min(1),
      isDefault: z.boolean().optional(),
      displayName: z.string().optional(),
      hidden: z.boolean().optional(),
      defaultReasoningEffort: z.string().nullish(),
      supportedReasoningEfforts: z.array(z.looseObject({ reasoningEffort: z.string() })).optional(),
    }),
  ),
});
export type ModelListResult = z.infer<typeof ModelListResultSchema>;

// ---------------------------------------------------------------------------
// Notification payloads
// ---------------------------------------------------------------------------

export const FileUpdateChangeSchema = z.looseObject({
  path: z.string(),
  diff: z.string().optional(),
  kind: z.looseObject({ type: z.string() }).optional(),
});

export const ThreadItemSchema = z.looseObject({
  id: z.string().optional(),
  type: z.string(),
  text: z.string().optional(),
  status: z.string().optional(),
  command: z.string().optional(),
  cwd: z.string().optional(),
  exitCode: z.number().nullish(),
  aggregatedOutput: z.string().nullish(),
  durationMs: z.number().nullish(),
  changes: z.array(FileUpdateChangeSchema).optional(),
  tool: z.string().optional(),
  server: z.string().optional(),
  error: z.unknown().optional(),
  content: z.unknown().optional(),
});
export type ThreadItem = z.infer<typeof ThreadItemSchema>;

export const ItemNotificationSchema = z.looseObject({
  threadId: z.string().optional(),
  turnId: z.string().optional(),
  item: ThreadItemSchema,
});

export const TurnNotificationSchema = z.looseObject({ threadId: z.string().optional(), turn: TurnSchema });

export const ThreadStartedNotificationSchema = z.looseObject({ thread: ThreadSchema });

export const ErrorNotificationSchema = z.looseObject({
  threadId: z.string().optional(),
  turnId: z.string().optional(),
  error: TurnErrorSchema,
  willRetry: z.boolean().optional(),
});

export const TokenUsageNotificationSchema = z.looseObject({
  threadId: z.string().optional(),
  turnId: z.string().optional(),
  tokenUsage: z.unknown(),
});

// ---------------------------------------------------------------------------
// Server -> client request payloads we inspect before answering
// ---------------------------------------------------------------------------

/**
 * `mcpServer/elicitation/request` parameters (McpServerElicitationRequestParams).
 *
 * The installed server sends this both for a genuine MCP form — a server
 * asking the human for data — and, with `_meta.codex_approval_kind` set to
 * `mcp_tool_call`, as the authorization gate in front of every MCP tool call.
 * Only `serverName` is guaranteed; everything else is optional here so an
 * older or newer server still decodes, and a field the coordinator needs but
 * did not get simply fails the authorization check instead of the parse.
 *
 * Recorded from codex-cli 0.147.0; see docs/runtime-codex.md.
 */
export const McpElicitationParamsSchema = z.looseObject({
  serverName: z.string(),
  threadId: z.string().optional(),
  turnId: z.string().nullish(),
  /** `form` (a typed schema), `openai/form`, or `url` (an out-of-band flow). */
  mode: z.string().optional(),
  message: z.string().optional(),
  requestedSchema: z
    .looseObject({
      type: z.string().optional(),
      properties: z.record(z.string(), z.unknown()).optional(),
      required: z.array(z.string()).nullish(),
    })
    .optional(),
  _meta: z.looseObject({ codex_approval_kind: z.string().optional() }).optional(),
});
export type McpElicitationParams = z.infer<typeof McpElicitationParamsSchema>;

/** The `_meta.codex_approval_kind` value that marks an elicitation as "may this MCP tool run?". */
export const MCP_TOOL_CALL_APPROVAL_KIND = 'mcp_tool_call';

// ---------------------------------------------------------------------------
// Error classification (foundation for FR053; kept honest, never invented)
// ---------------------------------------------------------------------------

export type CodexErrorClass = 'usage_limit' | 'authentication' | 'provider_transient' | 'context_window' | 'sandbox' | 'request_rejected' | 'unknown';

/**
 * Map the server's `codexErrorInfo` to a coarse class. The value is either a
 * string enum or a single-key object (for example `{ httpConnectionFailed: … }`),
 * and unknown values stay `unknown` rather than being guessed at.
 */
export function classifyCodexError(codexErrorInfo: unknown): CodexErrorClass {
  const tag = typeof codexErrorInfo === 'string' ? codexErrorInfo : typeof codexErrorInfo === 'object' && codexErrorInfo !== null ? Object.keys(codexErrorInfo)[0] : undefined;
  switch (tag) {
    case 'usageLimitExceeded':
    case 'sessionBudgetExceeded':
      return 'usage_limit';
    case 'unauthorized':
      return 'authentication';
    case 'serverOverloaded':
    case 'internalServerError':
    case 'httpConnectionFailed':
    case 'responseStreamConnectionFailed':
      return 'provider_transient';
    case 'contextWindowExceeded':
      return 'context_window';
    case 'sandboxError':
      return 'sandbox';
    case 'badRequest':
    case 'cyberPolicy':
      return 'request_rejected';
    default:
      return 'unknown';
  }
}

// ---------------------------------------------------------------------------
// Policy -> sandbox mapping (plan section 8 execution profiles)
// ---------------------------------------------------------------------------

export type SandboxMode = 'read-only' | 'workspace-write' | 'danger-full-access';

/**
 * `analysis` and `verification` read the granted snapshot only;
 * `local-development` writes the granted candidate and nothing else.
 * `danger-full-access` is never produced by this mapping.
 */
export function sandboxModeForPolicy(policy: Policy): Exclude<SandboxMode, 'danger-full-access'> {
  switch (policy) {
    case 'analysis':
    case 'verification':
      return 'read-only';
    case 'local-development':
      return 'workspace-write';
    default: {
      const never: never = policy;
      throw new Error(`unmapped policy ${String(never)}`);
    }
  }
}

export type SandboxPolicyPayload =
  | { readonly type: 'readOnly'; readonly networkAccess: false }
  | {
      readonly type: 'workspaceWrite';
      readonly writableRoots: ReadonlyArray<string>;
      readonly networkAccess: false;
      /** `/tmp` and `$TMPDIR` are writable by default under workspace-write; both are excluded so the granted roots are the whole writable set. */
      readonly excludeSlashTmp: true;
      readonly excludeTmpdirEnvVar: true;
    };

/**
 * The turn-scoped sandbox policy. `thread/start` only accepts the coarse
 * `SandboxMode` enum, so the writable roots — the part that actually bounds
 * the worker — are supplied per turn through `turn/start.sandboxPolicy`.
 */
export function sandboxPolicyForTurn(policy: Policy, writableRoots: ReadonlyArray<string>): SandboxPolicyPayload {
  if (sandboxModeForPolicy(policy) === 'read-only') return { type: 'readOnly', networkAccess: false };
  return { type: 'workspaceWrite', writableRoots: [...writableRoots], networkAccess: false, excludeSlashTmp: true, excludeTmpdirEnvVar: true };
}
